    static func sum(_ word: Substring, bold: Bool = false) -> Double? {
        let t = bold ? Self.bold : table
        var total = 0.0
        var afterJoiner = false
        for u in word.unicodeScalars {
            if u.value == 0x200D { afterJoiner = true; continue }
            if afterJoiner, u.value == 0xDBB { afterJoiner = false; continue }
            if afterJoiner, u.value == 0xDBA { afterJoiner = false; total += 0.105; continue }
